"""Reference registry and deterministic level diagrams. Never generates concept art."""
import json, pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
BASE=ROOT/'Docs/Art/Bellheart'
entries=[]
def add(folder,subject,view,description,assets,details='',status='planned'):
    stem=f'CW_BH_{subject}_{view}_V001' if view else f'CW_BH_{subject}_V001'
    entries.append(dict(id='BH-'+subject.replace('_','-')+('-'+view.replace('_','-') if view else ''),name=description,category=folder.split('_',1)[1],file=f'{folder}/{stem}.png',status=status,description=description,purpose=details or description,used_by=assets.split(','),views=view,version=1,provenance='pending',review_notes=[],prompt=details))
add('01_Island','ISLAND','MASTER_AERIAL','Entire Bellheart Isle master','L_Bellheart','Entire island elevated south-to-north view; exact canonical spatial plan from style bible.')
for view,desc in [('TOPDOWN','Measured north-up level map'),('GAMEPLAY_FLOW','Traversal and quest routing'),('ELEVATION','Terrain and landmark elevations')]:add('01_Island','ISLAND',view,desc,'L_Bellheart',desc)
add('02_BellTower','BELLTOWER','MASTER','Bell Tower master','SM_BH_BellTower,BP_BH_BellMechanism','Hero south-east view. Four pale limestone corner piers, 8x7m footprint, 32m tall, pointed front arch, single bronze bell at top, timber service deck, east exterior stair, broken west parapet, split-bell teal banner. Human scale figure 1.8m.')
add('02_BellTower','BELLTOWER','TURNAROUND','Bell Tower orthographic elevations','SM_BH_BellTower','Four labeled FRONT / EAST SIDE / REAR / WEST SIDE views of exactly the reference tower, aligned heights and same openings. Neutral cream background. No perspective invention.')
add('02_BellTower','BELLTOWER','INTERIOR','Bell Tower accessible service deck','SM_BH_BellTower,BP_BH_BellMechanism','Interior cutaway revealing stair arrival, timber maintenance deck, bronze bell suspension, reachable missing clapper socket and safety rail. Same tower.')
add('02_BellTower','BELLTOWER','BELL_MECHANISM','Bellheart installation mechanism','SM_BH_Bellheart,BP_BH_BellMechanism','Mechanical detail sheet, assembled and exploded views: bronze bell yoke, pivot, pendant socket, removable bronze clapper with teal inlay and split-bell motif. Installation lever accessible from timber service deck. Show 70cm clapper.')
add('04_FishingShop','FISHSHOP','MASTER','The Cloud Catch master','SM_BH_FishingShop,BP_BH_FishingShop','9x7m building, 6.2m high single swept teal-shingle gable, pale stone plinth, honey oak frame. West stone chimney, south covered counter with rope-wrapped posts, east door, north stockroom window. Oval hanging fish sign THE CLOUD CATCH. Mira not necessary in architectural master.')
add('04_FishingShop','FISHSHOP','EXTERIOR_TURNAROUND','The Cloud Catch exterior elevations','SM_BH_FishingShop','Same shop orthographic FRONT / EAST SIDE / REAR / WEST SIDE. Align ridge, counter, chimney and door positions. No redesigned roof.')
add('04_FishingShop','FISHSHOP','INTERIOR','The Cloud Catch interior','SM_BH_FishingShop,BP_BH_FishingShop','Same shop interior viewed through south counter, rods, bait jars, hook drawers, nets, rope, buckets, brass weighing scale, lanterns, shelves, fish trophy, teal cloth. Keep central work aisle readable. West chimney, east door.')
add('04_FishingShop','FISHSHOP','COUNTER_DISPLAY','Mira counter and physical merchandise','BP_BH_ShopDisplay','Two-panel counter closeup and item-display elevation, same shop. Rod stand left, bait jars center, hook/line spools right, teal mats and simple bronze price tags. No giant menu.')
add('05_Blacksmith','BLACKSMITH','MASTER','Bram’s Forge master','SM_BH_Blacksmith,BP_BH_Blacksmith','11x8m,6.8m ridge, asymmetric swept teal gable, pale stone west forge/chimney, oak south sales counter, east hand-cranked grindstone, rear anvil bay, hanging original split-bell banner. Broad welcoming silhouette, detailed joinery, same warm crafted quality as supplied forge.')
add('05_Blacksmith','BLACKSMITH','EXTERIOR_TURNAROUND','Bram’s Forge front side rear','SM_BH_Blacksmith','Aligned FRONT / EAST / REAR views of same building. Preserve west chimney, east grindstone, south counter and asymmetric teal roof.')
add('05_Blacksmith','BLACKSMITH','INTERIOR_COUNTER_STATION','Bram’s Forge interior and sharpening details','SM_BH_Blacksmith,BP_BH_Sharpening','Three useful panels: spacious interior with west forge and rear tool wall; knife on teal counter mat; east grindstone crank/axle/support close-up. Same building; warm daylight and small lantern pools. No character redesign.')
for folder,sub,name,desc in [('06_ElderHouse','ELDERHOUSE','Bellkeeper’s House','8x7m,6m ridge, teal gable, east limestone chimney, south arched door, west round study window. Old maps, books, bronze bells, fireplace, quest table.'),('07_Workshop','WORKSHOP','Tinker’s Workshop','12x9m,7m ridge, teal main gable with sawtooth annex, wide south skiff repair doors, east external pulley crane, west loft window. Skiff hull jig, rope hoists, repair bench and parts.')]:
    add(folder,sub,'MASTER',name+' exterior master','SM_BH_'+sub,desc+' South-east exterior three-quarter with small side elevation inset.')
