add('13_Bellcrab','BELLCRAB','MASTER','Bellcrab boss master','SK_BH_Bellcrab,BP_BH_Bellcrab','Original fantasy crab 4.8m wide claws extended,2.2m high,3.5m deep. Six walking legs plus two large blunt claws, chunky domed stone-blue shell with three bronze fragments, warm ochre joints. Teal inset weakpoint under central hinged bronze shell plate, split-bell motif. Non-grotesque readable friendly-dangerous silhouette. Three-quarter on cream backdrop, 1.8m human scale.')
add('13_Bellcrab','BELLCRAB','TURNAROUND','Bellcrab aligned turnaround','SK_BH_Bellcrab','Same boss FRONT / SIDE / REAR / TOP, exactly six walking legs plus two claws, same three bronze fragments and weakpoint plate. Neutral backdrop with scale markers.')
add('13_Bellcrab','BELLCRAB','ATTACK_WEAKPOINT_SCALE','Boss telegraphs and weakpoint','ABP_BH_Bellcrab,BP_BH_Bellcrab','Same boss multi-panel animation reference: raised claw slam telegraph, forward charge crouch, double swipe broad arc, opened central bronze plate exposing teal weakpoint, 1.8m human beside4.8m boss. Arrows only indicate attacks, not extra limbs.')
for sub,title,assets,desc in [('RODS','Old Rod and Basic Rod','SM_BH_OldRod,SM_BH_BasicRod','Old Rod 190cm tapered weathered oak simple iron reel, cord wraps; Basic Rod 210cm straight honey oak, brass reel, reinforced teal wraps. Side, reel detail and line-guide detail of both.'),('KNIFE_LINE_HOOK','Iron Knife, Reinforced Line and Basic Hook','SM_BH_IronKnife,SM_BH_ReinforcedLine,SM_BH_BasicHook','28cm iron working knife, broad single-edge blade, leather cord grip, bronze ring pommel;12cm line spool dark iron with cord;3cm bronze fishing hook. Orthographic and three-quarter views each, measured scale, no modern plastic.'),('BAIT_BASKET','Bellcrab Bait and Fish Basket','SM_BH_BellcrabBait,SM_BH_FishBasket','15cm bronze chime-lure enclosed in braided teal bait bundle with hook eye;55x35x40cm woven willow fish basket, leather shoulder strap, hinged lid, broad opening. Multiple angles and materials.'),('BELLHEART','Bellheart quest object','SM_BH_Bellheart','70cm tall bronze bell clapper, rounded weighted lower bulb, narrow neck, keyed top pivot eye, teal inlay ring, original split-bell emblem. Side/front/top and hand scale. Must fit tower socket; portable with both hands.')]:add('14_Items','ITEM',sub,title,assets,desc+' Clean cream modeling reference sheet, plausible crafted construction.')
add('14_Items','FP','ROD_HELD','First-person rod presentation','SK_BH_PlayerArms,SM_BH_BasicRod','Player eye168cm. Both believable gloved hands, fingerless brown leather, cream sleeves; basic oak rod and brass reel held lower right, line guides visible, center view unobstructed. Fishing pond background softly simplified. No UI. Correct hand anatomy.')
add('14_Items','FP','KNIFE_HELD','First-person knife presentation','SK_BH_PlayerArms,SM_BH_IronKnife','Same hands/gloves/sleeves as rod view.28cm iron knife in right hand low ready pose; open left hand lower-left. Three small grip/attack follow-through details. Center view unobstructed, village backdrop, no gore/no UI.')
for sub,desc in [('WOOD','crate, barrel, bucket, bench, table, carved sign, two-rail fence section, dock post'),('FISHING','net, coiled rope, hook, cork float, bait jar, fish rack, rod stand, fish basket'),('FORGE','anvil, hand-cranked grindstone, hammer, tongs, wall tool rack'),('VILLAGE','warm lantern, teal split-bell banner, flower pot, striped teal/cream market awning, notice board, small bronze bell ornament')]:add('15_Props','PROPSET',sub,sub.title()+' prop family','SM_BH_Props_'+sub,'Labeled reusable prop family sheet: '+desc+'. Same honey oak/dark timber/pale stone/bronze/teal materials, generous spacing, separate 3/4 objects and a 1m scale ruler, no random extra props.')
add('00_Style','MATERIAL','BIBLE','Material and surface swatches','M_BH_Master','Fourteen labeled samples: honey oak, dark timber, pale limestone, weathered limestone, bronze, iron, rope, teal fabric, cream cloth, leather, meadow grass, cream flowers, turquoise water, teal roof shingles. Stylized crafted believable surfaces, broad detail not noisy grime. Palette from bible, daylight-neutral presentation.')
for sub,desc in [('DAY_MASTER','Full island late-morning sunlight study matching master aerial camera and layout, warm southwest sun, cool fill, clouds and turquoise pond.'),('SHOP_INTERIOR','Inside Bram forge toward south counter and sunlit village; warm lantern bounce, readable dark timber and tools, no night lighting.'),('BELLTOWER','Same tower viewed up northern path; pale stone remains detailed in warm sun, blue sky, soft shadows, bronze bell clear.')]:add('17_Lighting','LIGHTING',sub,'Lighting '+sub.lower().replace('_',' '),'L_Bellheart',desc+' Small exposure/color swatches optional, no sunset, no bloom haze obscuring structure.')
for sub,desc in [('HUD_MASTER','Full original HUD over pond eye-level view: lower-left heart100/100, lower-center four small slots rod/knife/line/basket, upper-right crown32, quest below THE MISSING BELLHEART / Speak to Orin, tiny crosshair and E Interact, small Cloudfin landed notice.'),('SHOP_DIALOGUE','Two clearly separated UI studies over muted world: SHOP small teal card IRON KNIFE / Damage8 to18 /24 crowns /E Buy; DIALOGUE lower narrow panel MIRA / The pond is restless today. / Tell me about fishing. / Show me your supplies. Readable cream typography and restrained bronze corners.'),('FISHING_QUEST','Two clearly separated original UI studies: compact fishing tension arc and HOLD TO REEL with release hint; quest update panel THE MISSING BELLHEART / Bring the bronze fragment to Orin with three small checklist rows. No giant menus.')]:add('16_UI','UI',sub,'UI '+sub.lower().replace('_',' '),'WBP_BH_'+sub,desc+' Fantasy crafted but highly legible UI, dark teal backing, original simple crown and split-bell icon. Do not trace supplied HUD.')
for sub,desc in [('ARRIVAL_FISHING_MIRA','Three wide cinematic gameplay panels: first-person arrival at south dock looking north; fishing central pond from south bank toward village; talking to Mira at western fishing-shop counter. Same island and Mira.'),('FORGE_PATH_BOSS','Three wide gameplay panels: shopping at Bram forge, walking north from plaza toward same bell tower, Bellcrab emerging onto eastern pond bank. Same Bram and boss references.'),('COMBAT_INSTALL_FINALE','Three wide gameplay panels: first-person knife against telegraphing Bellcrab on eastern arena; carrying/installing70cm Bellheart at tower service-deck socket; bronze bell ringing with clearing cloud band and restored village below. Late morning throughout.')]:add('01_Island','GAMEPLAY',sub,'Gameplay moments '+sub.lower().replace('_',' '),'L_Bellheart',desc+' Actual playable first-person framing with restrained minimal HUD, gloves consistent. These are concept targets not screenshots.')
def save():
    old={e['id']:e for e in json.loads((BASE/'reference_manifest.json').read_text()).get('references',[])} if (BASE/'reference_manifest.json').exists() else {}
    for e in entries:
        if e['id'] in old:e.update({k:v for k,v in old[e['id']].items() if k in ['status','provenance','review_notes','sha256','source_path','dependencies']})
    (BASE/'reference_manifest.json').write_text(json.dumps({'schema_version':1,'phase':'0','complete':False,'style_bible':'BELLHEART_STYLE_BIBLE.md','references':entries},indent=2),encoding='utf-8')
    print(len(entries),'planned sheets')
if __name__=='__main__':save()
